import { expectStatus, test } from "../../fixtures";

test("Audit trails from another tenant are invisible", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in tenant "Globex Procurement" (the otherTenant persona, member@globex.test)
  const vendor = await factory.vendor({ as: "otherTenant" });
  const member = await apiAs("member");

  // Act
  const response = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
